$:set -euo pipefail
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'

"use strict";
const fs=require("fs"),assert=require("assert");
const read=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const write=(p,x)=>fs.writeFileSync(p,JSON.stringify(x,null,2)+"\n");
const scopePath="Tasks/TasksCompleted/user-prompt-task-1794192853-accepted-instruction.json";
const analyticsPath="Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json";
const taskPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json";
const draftPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const rulesPath="references/rules-template.json";
const dialectPath="references/machine-dialect-rules.json";
for(const p of [rulesPath,dialectPath,scopePath,analyticsPath,taskPath]) assert(fs.existsSync(p),"Missing "+p);
assert(!fs.existsSync(draftPath),"Draft exists: do not overwrite");
const scope=read(scopePath),analytics=read(analyticsPath),task=read(taskPath);
assert.strictEqual(task.status,"pending_revision");
assert.deepStrictEqual(Object.keys(scope),["applicability","model","examples"]);
assert(scope.examples.length===10);
assert(Array.isArray(analytics)&&analytics.length===3);
const wrapper=[
  {
    title:"Account Custom Instruction Container",
    applicability:"Governs the interpretation of the account custom-instruction collection. Each following entry contains one complete standalone rule object or one subject-specific grouped-rule array.",
    rules_template_path:rulesPath,
    machine_dialect_rules_path:dialectPath,
    governing_references:"The referenced structural and machine-dialect rule sets define how entries in this array are organized, written, and interpreted. They are stored independently; their definitions are not reproduced in this explainer."
  },
  {title:"User-Defined Operational Scope",...scope},
  [
    {
      title:"Conversation Analytics",
      applicability:"Applies to instructions for generating and persisting completed-turn conversation-analytics records belonging to the current conversation.",
      subject_scope:"This group contains only conversation-analytics recording requirements. It does not authorize recording other conversations, changing unrelated custom instructions, or asserting a persistence operation that has not been verified.",
      local_interpretation:"Interpret the subordinate recording requirement within this conversation-analytics subject. Inherited structural and semantic writing rules remain in force unless a specific conflicting local interpretation is explicitly defined."
    },
    {title:"End-of-Turn Conversation Analytics Recording",...analytics[1]}
  ]
];
write(draftPath,wrapper);
const check=read(draftPath);
assert(Array.isArray(check)&&check.length===3);
assert.deepStrictEqual(check[1].model,scope.model);
assert.deepStrictEqual(check[1].examples,scope.examples);
assert(check[0].rules_template_path===rulesPath&&check[0].machine_dialect_rules_path===dialectPath);
assert(check[2][0].title==="Conversation Analytics");
const {title,...analyticsBody}=check[2][1];
assert.deepStrictEqual(analyticsBody,analytics[1]);
const old=task.task.requirements;
task.task.previous_requirements_before_current_revision=old;
const requirements=[
"Represent account custom instructions as one outer JSON array with a permanently pinned explainer object at index 0.",
"Store the structural rules template separately at references/rules-template.json and refer to it through the outer explainer's rules_template_path member, rather than defining the template inside itself.",
"Store machine-dialect writing rules and examples separately at references/machine-dialect-rules.json and refer to them through the outer explainer's machine_dialect_rules_path member.",
"Use self-describing, context-complete machine dialect in every explainer, standalone rule, group rule, and nested instructional member; valid JSON by itself is insufficient.",
"Allow verbose multi-member explainer and rule objects where their context, conditions, and relationships require it; avoid undefined, artificial pseudo-machine brevity.",
"Make each standalone rule one complete object occupying exactly one parent-array index and including a descriptive title, however many nested models, requirements, and examples the rule contains.",
"Represent each subject-specific group as one nested array occupying one index of its parent, containing only one subject and a titled index-zero group explainer.",
"Keep the explainer of every outer and nested array pinned at index 0 throughout changes.",
"Insert newly adopted outer entries at index 1, shifting older entries without changing their contents or relative order.",
"Insert newly adopted entries within an inner group at index 1, preserving its pinned explainer and existing entry order.",
"Apply explicit local interpretation overrides only within the group where defined and preserve all nonconflicting inherited instructions.",
"Preserve substantive rule requirements; when inserting the accepted user scope rule add only its title, leaving its applicability, model, and ten examples identical.",
"Provide an instantiated wrapper draft containing the accepted user scope rule as one outer rule object and a nested conversation-analytics group without falsely asserting activation."
];
task.task.requirements=requirements.map((requirement,i)=>({id:"R"+String(i+1),requirement}));
task.task.deliverable="Two detailed JSON reference rule sets in references/, each containing examples, and a JSON wrapper draft in the task queue referencing both documents while preserving the accepted user scope rule and the conversation-analytics rule.";
task.task.acceptance_criteria=[
"An outer array exists with index-zero explainer referencing both rule-set paths; no self-redefinition of template structure is embedded there.",
"Every nested group has a titled index-zero explainer identifying its single subject.",
"Complete standalone rules are represented as whole titled objects occupying one array index.",
"New entries are inserted at index 1 while array explainers stay at index 0.",
"Both reference files define contextual machine-readable requirements and concrete examples.",
"The accepted scope rule's applicability, model, and ten examples are unchanged.",
"The analytics rule body is semantically intact and not represented as operationally activated.",
"The revision draft remains pending user acceptance, with the previously rejected artifacts preserved."
];
task.task.resolved_design_decisions=[
{id:"D1",decision:"The explainer is pinned at index 0 in all instruction arrays; former final-index explainer semantics are superseded."},
{id:"D2",decision:"New outer and inner entries are inserted at index 1; indices of existing entries shift without changing contents or order."},
{id:"D3",decision:"Every standalone rule is a single complete object with a title; a group is one nested array whose index-zero explainer contains a group title."},
{id:"D4",decision:"Rules and explainers use semantically complete, contextual machine dialect; pseudo-machine shorthand without defined meaning is unacceptable."},
{id:"D5",decision:"The array structural rules and the rule-writing rules are separate referenced documents with examples, not copied into the outer index-zero explainer."}
];
task.task.amendments.push({purpose:"Apply latest user revisions to the wrapper design without treating the design as accepted before review.",user_instruction_summary:"Store detailed structural rules and examples in a separate Terminals references rules template; store a second reference document for machine-dialect writing requirements and examples; reference both from the wrapper's index-zero explainer, preserving the accepted verbose user scope rule as one titled object."});
task.revision_draft={status:"pending_review",files:[rulesPath,dialectPath,draftPath],accepted_scope_source:scopePath,analytics_source:analyticsPath,account_settings_updated:false};
write(taskPath,task);
assert(read(taskPath).revision_draft.files.length===3);
assert(read(taskPath).status==="pending_revision");
console.log("WRAPPER_DRAFT_VALID",wrapper.length,"outer entries");
console.log("SCOPE_MODEL_AND_TEN_EXAMPLES_IDENTICAL");
console.log("ANALYTICS_RULE_BODY_IDENTICAL");
console.log("RULES_TEMPLATE_PATH",rulesPath);
console.log("MACHINE_DIALECT_RULES_PATH",dialectPath);
console.log("TASK_STATUS",task.status,task.revision_draft.status);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json'
git diff --cached --check
git commit -m 'Draft instruction wrapper referencing external structural and authoring rules'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
